mapper.select:
SELECT t.id, t.module, t.action, t.target_id AS targetId, t.operator_id AS operatorId, t.biz_type AS bizType, t.ip, t.create_time AS createTime, t.before_value AS beforeValue, t.after_value AS afterValue, u.name AS operatorName FROM ad_operation_log t LEFT JOIN sys_user u ON u.id = t.operator_id WHERE t.organization_id = #{orgId}
AND t.module = #{request.module}
AND t.action = #{request.action}
AND t.operator_id = #{request.operator}
AND t.create_time BETWEEN #{request.startTime} AND #{request.endTime}
AND (t.target_id LIKE CONCAT('%', #{request.keyword}, '%') OR t.biz_type LIKE CONCAT('%', #{request.keyword}, '%'))
ORDER BY t.create_time DESC
